// Digital twin for Drive.P — Boréas BOS1921 piezoelectric haptic driver.
//
// A high-voltage piezo driver: an integrated boost converter (fed from V_DRIVE,
// pad 9) swings a differential output OUT+/OUT- (pads 7/8) up to 190 Vpp (±95 V)
// to drive a piezo actuator, and the same pins sense the piezo's voltage for
// touch detection. Logic runs off V+ (pad 10). I²C on pads 4/5, GPIO on pad 3.
//
// Output-centric like Drive.H: firmware picks a mode + writes samples (FIFO) or
// reads the sense channel. This twin models the drive envelope (0..1) on OUT±,
// the sense/touch readback, status/fault, and the two-supply power layer.
//
// Conversions are datasheet/driver-accurate (canonical): full-scale 190 Vpp
// (±95 V high-V, ±13.28 V low-V), sense 7.6 mV/LSB fine · 54.5 mV/LSB coarse,
// 12-bit signed samples, IC_STATUS state/fault bits. The V_DRIVE power layer is
// a CV²f + HV-hold model (see the constants block) fit to the datasheet's
// average-supply-current anchors — it tracks amplitude, tone frequency, output
// range, piezo load and supply voltage — but keeps an inferred loss/efficiency
// factor, so the power layer is tagged "inferred".
import type { TileSim } from '../tileSim';

const I2C_ADDR = 0x44;
const CHIP_ID = 0x0781;

// return-register selector (COMM.RDADDR) that read() reflects
const REG_IC_STATUS = 0x10;
const REG_SENSE_VAL = 0x18;
const REG_CHIP_ID = 0x1e;

// modes (drive_p_mode_t)
const MODE_IDLE = 0;
const MODE_SENSE_FINE = 1;
const MODE_SENSE_COARSE = 2;
const MODE_PLAY_DIRECT = 3;
const MODE_PLAY_FIFO = 4;
const MODE_PLAY_RAM_SYNTH = 5;

// IC_STATUS fields
const STATE_IDLE = 0x0000;
const STATE_RUNNING = 0x0200;
const STATE_ERROR = 0x0300;
const FAULT_BITS = 0x0004; // a representative fault bit within FAULT_MASK 0x00FC

const SAMPLE_FS = 2047; // 12-bit signed full-scale
const UVLO_MV = 3000; // V_DRIVE minimum (boost won't run below this)

// Power model — V_DRIVE (VBUS) draw, anchored on BOS1921 datasheet Table 7
// (IBUS,AVG; conditions Vbus = 3.6 V). A piezo is a capacitor, so the boost
// supply current is dominated by reactive energy ≈ C·V²·f, plus a static cost to
// hold the high-voltage rail. While driving:
//     I_VDRIVE = IDLE + K_STATIC·Vpk            (HV-hold; fit to DC anchor)
//                     + K_DYN·C·Vpp²·f / Vbus   (reactive CV²f; fit to 90 mA)
// Datasheet anchors: sleep 0.6 µA / 2.4 µA w/ retention · idle 530 µA ·
//   DC-hold 3.7 mA @ 95 V · 90 mA @ 190 Vpp / 300 Hz / 100 nF.
// Validation point (190 Vpp / 200 Hz / 10 nF) predicts ~9.5 mA vs 14.5 mA spec
// (~1.5× low — small-cap fixed/switching losses aren't separated out), so the
// power layer stays "inferred" despite the datasheet-anchored shape.
const IQ_SLEEP_RET_UA = 2.4;
const IQ_SLEEP_NORET_UA = 0.6;
const IDLE_UA = 530;
const VPLUS_ACTIVE_UA = 50; // V+ logic/IO (small; datasheet lumps Iq under V_DRIVE)
const K_STATIC_UA_PER_V = 33.4; // HV-hold: 95 V → +3.17 mA over idle (DC anchor)
const K_DYN = 0.287; // reactive coefficient (A·V / F·V²·Hz), fit to the 90 mA anchor
const DEFAULT_LOAD_NF = 100; // datasheet characterization load (actuator is external)

interface State {
  // ── inputs (controls) ──
  supply_mv: number; // V_DRIVE (boost supply)
  amplitude: number; // last FIFO/reference sample magnitude, 0..2047
  freq_hz: number; // waveform/tone frequency (drives reactive power)
  load_nf: number; // external piezo capacitance
  mode: number;
  sense_mv: number; // externally applied piezo voltage (for sense/touch)
  fault: number; // chip fault/error
  sleeping: number; // SLEEP state

  // ── config ──
  output_range: number; // 0 = ±95 V (high-V), 1 = ±13.28 V (low-V)
  sense_gain: number; // 1 = fine 7.6 mV/LSB, 0 = coarse 54.5 mV/LSB
  retain: number; // RET: retain RAM/regs in sleep
  auto_sleep: number; // TOUT
  upi: number; // unidirectional power input
  return_reg: number; // which register read() reflects

  [field: string]: number;
}

const pick = (args: number[], i: number, cur: number) =>
  args.length > i && Number.isFinite(args[i]) ? args[i] : cur;
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

const isPlayMode = (m: number) =>
  m === MODE_PLAY_DIRECT || m === MODE_PLAY_FIFO || m === MODE_PLAY_RAM_SYNTH;
const powered = (s: State) => s.sleeping !== 1 && s.supply_mv >= UVLO_MV;

// Differential drive envelope magnitude 0..1 (the |OUT± swing| / full-scale).
function driveStrength(s: State): number {
  if (!powered(s) || !isPlayMode(s.mode)) return 0;
  return clamp(s.amplitude / SAMPLE_FS, 0, 1);
}

// Full-scale peak output for the active range, in mV (±95 V or ±13.28 V).
const outFsMv = (s: State) => (s.output_range === 1 ? 13_280 : 95_000);

// Sense channel: applied piezo mV → signed 12-bit raw at the active LSB.
function senseRaw(s: State): number {
  const lsbTenthsMv = s.sense_gain === 1 ? 76 : 545; // 7.6 / 54.5 mV in 0.1 mV
  const raw = Math.round((s.sense_mv * 10) / lsbTenthsMv);
  return clamp(raw, -2048, 2047);
}

function statusWord(s: State): number {
  if (s.fault === 1) return STATE_ERROR | FAULT_BITS;
  return driveStrength(s) > 0 ? STATE_RUNNING : STATE_IDLE;
}

// What a generic read() returns, per the selected return register.
function readReturn(s: State): number {
  if (s.return_reg === REG_SENSE_VAL) return senseRaw(s) & 0x0fff;
  if (s.return_reg === REG_CHIP_ID) return CHIP_ID;
  return statusWord(s); // IC_STATUS default
}

const sim: TileSim<State> = {
  tile: 'Drive.P',

  defaultState: {
    supply_mv: 3700,
    amplitude: 0,
    freq_hz: 200,
    load_nf: DEFAULT_LOAD_NF,
    mode: MODE_IDLE,
    sense_mv: 0,
    fault: 0,
    sleeping: 0,

    output_range: 0, // ±95 V
    sense_gain: 1, // fine
    retain: 1,
    auto_sleep: 0,
    upi: 0,
    return_reg: REG_CHIP_ID, // post-reset default
  },

  controls: [
    { type: 'slider', field: 'amplitude', label: 'Drive amplitude', min: 0, max: 2047, step: 1 },
    {
      type: 'slider',
      field: 'freq_hz',
      label: 'Tone frequency',
      min: 0,
      max: 1000,
      step: 5,
      unit: 'Hz',
    },
    {
      type: 'slider',
      field: 'load_nf',
      label: 'Piezo load',
      min: 1,
      max: 470,
      step: 1,
      unit: 'nF',
    },
    { type: 'slider', field: 'mode', label: 'Mode (0 idle…5)', min: 0, max: 5, step: 1 },
    {
      type: 'slider',
      field: 'supply_mv',
      label: 'V_DRIVE supply',
      min: 2500,
      max: 5500,
      step: 50,
      unit: 'mV',
    },
    {
      type: 'slider',
      field: 'sense_mv',
      label: 'Sensed piezo V',
      min: -1000,
      max: 1000,
      step: 5,
      unit: 'mV',
    },
    { type: 'toggle', field: 'output_range', label: 'Low-V range (±13.28 V)' },
    { type: 'toggle', field: 'sense_gain', label: 'Fine sense (7.6 mV)' },
    { type: 'toggle', field: 'fault', label: 'Fault' },
    { type: 'toggle', field: 'sleeping', label: 'Sleep' },
  ],

  hostCalls: {
    // ── lifecycle ──
    tile_drive_p_find: () => ({ scalar: I2C_ADDR }),
    tile_drive_p_init: () => ({
      scalar: 0,
      nextState: {
        mode: MODE_IDLE,
        amplitude: 0,
        sleeping: 0,
        sense_gain: 1,
        output_range: 0,
        return_reg: REG_CHIP_ID,
      },
    }),
    tile_drive_p_reset: () => ({
      nextState: { mode: MODE_IDLE, amplitude: 0, fault: 0, sleeping: 0, return_reg: REG_CHIP_ID },
    }),
    tile_drive_p_sleep: () => ({ nextState: { sleeping: 1 } }),

    // ── mode + raw access ──
    tile_drive_p_set_mode: ({ args }) => {
      const mode = pick(args, 0, MODE_IDLE);
      const sense = mode === MODE_SENSE_FINE || mode === MODE_SENSE_COARSE;
      return {
        nextState: {
          mode,
          sleeping: 0,
          // SENSE_FINE/COARSE also pin the sense-gain bit
          ...(mode === MODE_SENSE_FINE ? { sense_gain: 1 } : {}),
          ...(mode === MODE_SENSE_COARSE ? { sense_gain: 0 } : {}),
          return_reg: sense ? REG_SENSE_VAL : REG_IC_STATUS,
        },
      };
    },
    tile_drive_p_read: ({ state }) => ({ scalar: readReturn(state) }),
    tile_drive_p_read_sense: ({ state }) => ({
      scalar: senseRaw(state),
      nextState: { return_reg: REG_SENSE_VAL },
    }),
    tile_drive_p_read_status: ({ state }) => ({
      scalar: statusWord(state),
      nextState: { return_reg: REG_IC_STATUS },
    }),
    tile_drive_p_write_fifo: ({ args }) => {
      const sample = pick(args, 0, 0);
      return { nextState: { amplitude: clamp(Math.abs(sample), 0, SAMPLE_FS) } };
    },
    tile_drive_p_write_reg: () => ({ nextState: {} }), // opaque register poke
    tile_drive_p_wfs_write: () => ({ nextState: {} }), // array arg not modeled
    tile_drive_p_check_and_recover: ({ state, args }) => {
      const needs = state.fault === 1 ? 1 : 0;
      const restore = pick(args, 0, state.mode);
      return { scalar: needs, nextState: needs ? { fault: 0, mode: restore } : {} };
    },

    // ── config setters ──
    tile_drive_p_set_output_range: ({ args }) => ({
      nextState: { output_range: pick(args, 0, 0) ? 1 : 0 },
    }),
    tile_drive_p_set_sense_gain: ({ args }) => ({
      nextState: { sense_gain: pick(args, 0, 1) ? 1 : 0 },
    }),
    tile_drive_p_set_sleep_retention: ({ args }) => ({
      nextState: { retain: pick(args, 0, 1) ? 1 : 0 },
    }),
    tile_drive_p_set_auto_sleep: ({ args }) => ({
      nextState: { auto_sleep: pick(args, 0, 0) ? 1 : 0 },
    }),
    tile_drive_p_set_upi: ({ args }) => ({ nextState: { upi: pick(args, 0, 0) ? 1 : 0 } }),

    // ── idiomatic playback helpers (set FIFO mode + a drive amplitude) ──
    tile_drive_p_play_click: ({ args }) => ({
      nextState: {
        mode: MODE_PLAY_FIFO,
        sleeping: 0,
        amplitude: Math.round((clamp(pick(args, 0, 100), 0, 100) / 100) * SAMPLE_FS),
      },
    }),
    tile_drive_p_play_sine: ({ state, args }) => ({
      nextState: {
        mode: MODE_PLAY_FIFO,
        sleeping: 0,
        freq_hz: pick(args, 0, state.freq_hz),
        amplitude: Math.round((clamp(pick(args, 1, 100), 0, 100) / 100) * SAMPLE_FS),
      },
    }),
    tile_drive_p_play_buzz: ({ args }) => ({
      nextState: {
        mode: MODE_PLAY_FIFO,
        sleeping: 0,
        freq_hz: 150, // driver's play_buzz uses a 150 Hz tone
        amplitude: Math.round((clamp(pick(args, 0, 100), 0, 100) / 100) * SAMPLE_FS),
      },
    }),
    tile_drive_p_play_pulse_train: ({ args }) => ({
      nextState: {
        mode: MODE_PLAY_FIFO,
        sleeping: 0,
        amplitude: Math.round((clamp(pick(args, 0, 100), 0, 100) / 100) * SAMPLE_FS),
      },
    }),
    tile_drive_p_play_samples: () => ({
      nextState: { mode: MODE_PLAY_FIFO, sleeping: 0, amplitude: SAMPLE_FS },
    }),

    // ── sensing helpers ──
    tile_drive_p_is_touched: ({ state, args }) => {
      const threshold = pick(args, 0, 0);
      const mv = Math.abs((senseRaw(state) * 76) / 10); // fine 7.6 mV/LSB → mV
      return {
        scalar: mv >= threshold ? 1 : 0,
        nextState: { mode: MODE_SENSE_FINE, sense_gain: 1, return_reg: REG_SENSE_VAL },
      };
    },
    tile_drive_p_play_on_touch: ({ state, args }) => {
      const threshold = pick(args, 1, 0);
      const mv = Math.abs((senseRaw(state) * 76) / 10);
      const touched = mv >= threshold ? 1 : 0;
      return {
        scalar: touched,
        nextState: touched
          ? {
              mode: MODE_PLAY_FIFO,
              amplitude: Math.round((clamp(pick(args, 0, 100), 0, 100) / 100) * SAMPLE_FS),
            }
          : { mode: MODE_SENSE_FINE, sense_gain: 1, return_reg: REG_SENSE_VAL },
      };
    },
    tile_drive_p_read_sense_samples: () => ({
      nextState: { mode: MODE_SENSE_FINE, sense_gain: 1, return_reg: REG_SENSE_VAL },
    }),
  },

  provenance: {
    // canonical — datasheet/driver-accurate
    tile_drive_p_find: 'canonical', // I2C 0x44
    tile_drive_p_read_sense: 'canonical', // signed 12-bit, 7.6 / 54.5 mV LSB
    tile_drive_p_read_status: 'canonical', // IC_STATUS state/fault bits
    tile_drive_p_set_mode: 'canonical', // CONFIG mode encoding
    tile_drive_p_set_output_range: 'canonical', // ±95 / ±13.28 V (GAIND)
    tile_drive_p_set_sense_gain: 'canonical', // GAINS
    tile_drive_p_write_fifo: 'canonical', // 12-bit signed reference sample
    tile_drive_p_is_touched: 'canonical', // 7.6 mV/LSB threshold compare
    // inferred — behavior obvious from the driver, not a datasheet number
    tile_drive_p_init: 'inferred',
    tile_drive_p_reset: 'inferred',
    tile_drive_p_sleep: 'inferred',
    tile_drive_p_check_and_recover: 'inferred',
    tile_drive_p_set_sleep_retention: 'inferred',
    tile_drive_p_set_auto_sleep: 'inferred',
    tile_drive_p_set_upi: 'inferred',
    tile_drive_p_play_click: 'inferred',
    tile_drive_p_play_sine: 'inferred',
    tile_drive_p_play_buzz: 'inferred',
    tile_drive_p_play_pulse_train: 'inferred',
    tile_drive_p_play_on_touch: 'inferred',
    tile_drive_p_read: 'inferred', // return-register multiplexing
    // hallucinated — array/opaque args not modeled
    tile_drive_p_write_reg: 'hallucinated',
    tile_drive_p_wfs_write: 'hallucinated',
    tile_drive_p_play_samples: 'hallucinated',
    tile_drive_p_read_sense_samples: 'hallucinated',
    power: 'inferred', // CV²f + HV-hold model fit to datasheet anchors; loss/efficiency factor inferred
  },

  // Differential drive envelope (magnitude 0..1) on the OUT+/OUT- pads.
  padOutputs(state) {
    const s = driveStrength(state);
    return { 'OUT+': s, 'OUT-': s };
  },

  // Electrical layer. Two supplies: V+ logic (pad 10) + V_DRIVE boost (pad 9);
  // the boosted differential drive appears on OUT± (pads 7/8) up to 190 Vpp.
  // V_DRIVE draw uses the CV²f + HV-hold model above (see the constants block),
  // anchored on datasheet Table 7 — so it responds to amplitude (Vpk), tone
  // frequency, output range (Vpk²), piezo load, and supply voltage.
  power(state) {
    const on = powered(state);
    const s = driveStrength(state);

    let driveUa: number;
    if (state.sleeping === 1) {
      driveUa = state.retain === 1 ? IQ_SLEEP_RET_UA : IQ_SLEEP_NORET_UA;
    } else if (state.supply_mv < UVLO_MV) {
      driveUa = 0;
    } else if (s <= 0) {
      driveUa = IDLE_UA; // output off — quiescent only
    } else {
      const vpk_v = (s * outFsMv(state)) / 1000; // peak output voltage (V)
      const vpp_v = 2 * vpk_v; // peak-to-peak swing (V)
      const c_f = (state.load_nf > 0 ? state.load_nf : DEFAULT_LOAD_NF) * 1e-9;
      const vbus_v = state.supply_mv / 1000;
      const staticUa = K_STATIC_UA_PER_V * vpk_v; // HV-hold (∝ Vpk)
      const dynUa = ((K_DYN * c_f * vpp_v * vpp_v * state.freq_hz) / vbus_v) * 1e6; // reactive CV²f
      driveUa = IDLE_UA + staticUa + dynUa;
    }
    const vplusUa = on ? VPLUS_ACTIVE_UA : 0;

    return {
      draw_ua: Math.round(driveUa + vplusUa),
      rails: [
        {
          name: 'V+',
          role: 'supply',
          v_mv: 1800,
          i_ua: vplusUa,
          pads: ['10'],
          note: 'logic/IO supply',
        },
        {
          name: 'V_DRIVE',
          role: 'supply',
          v_mv: state.supply_mv,
          i_ua: Math.round(driveUa),
          pads: ['9'],
          note:
            state.sleeping === 1
              ? 'boost supply — sleep'
              : s > 0
                ? 'boost supply + piezo drive'
                : 'boost supply — idle',
        },
        {
          name: 'OUT±',
          role: 'output',
          v_mv: Math.round(s * outFsMv(state)),
          pads: ['7', '8'],
          note: 'boosted differential piezo drive (190 Vpp full-scale)',
        },
      ],
    };
  },
};

export default sim;
